def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the central uniform divider.
    candidates = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            candidates.append(("row", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            candidates.append(("col", c))

    orient, k = min(
        candidates,
        key=lambda item: abs(item[1] - ((h if item[0] == "row" else w) - 1) / 2)
    )

    if orient == "col":
        left = [row[:k] for row in grid]
        right = [row[k + 1:] for row in grid]
        shared = set(v for row in left for v in row) & set(v for row in right for v in row)
        fill = max(shared, key=lambda v: sum(x == v for row in left + right for x in row))
        return [
            [3 if left[r][c] == right[r][c] else fill for c in range(len(left[0]))]
            for r in range(h)
        ]
    else:
        top, bottom = grid[:k], grid[k + 1:]
        shared = set(v for row in top for v in row) & set(v for row in bottom for v in row)
        fill = max(shared, key=lambda v: sum(x == v for row in top + bottom for x in row))
        return [
            [3 if top[r][c] == bottom[r][c] else fill for c in range(w)]
            for r in range(len(top))
        ]
